/* ==========================================================================
   Highland Horizons — Destinations Page Styles
   Uses shared color tokens and Libre Baskerville font from layout.css
   ========================================================================== */

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--hh-cream);
  font-family: var(--hh-font-serif);
  color: var(--hh-olive-green);
}

main {
  flex: 1 0 auto;
}

/* ==========================================================================
   HERO SECTION (Sage-green background + heading + subtitle + search bar)
   ========================================================================== */

.hh-hero {
  background-color: var(--hh-sage-green);
  border-bottom: 2px solid rgba(27, 94, 59, 0.2);
  padding: 3.25rem 1rem 3.5rem;
}

.hh-hero-inner {
  max-width: 760px;
}

.hh-hero-title {
  color: var(--hh-forest-green);
  font-size: clamp(1.9rem, 4vw, 2.75rem);
  font-weight: 700;
  line-height: 1.2;
  margin-bottom: 0.75rem;
}

.hh-hero-subtitle {
  color: #263621;
  font-size: clamp(1rem, 2vw, 1.15rem);
  line-height: 1.55;
  margin-bottom: 1.75rem;
}

.hh-hero-search {
  display: flex;
  align-items: stretch;
  gap: 0.5rem;
  max-width: 560px;
  margin: 0 auto;
  background-color: var(--hh-cream);
  border: 2px solid var(--hh-forest-green);
  border-radius: 10px;
  padding: 0.35rem;
  box-shadow: 0 4px 14px rgba(27, 94, 59, 0.12);
}

.hh-hero-search-input {
  border: 0;
  background-color: transparent;
  color: var(--hh-forest-green);
  font-family: var(--hh-font-serif);
  font-size: 0.95rem;
  padding: 0.55rem 0.75rem;
  min-width: 0;
}

.hh-hero-search-input::placeholder {
  color: rgba(63, 79, 58, 0.72);
}

.hh-hero-search-input:focus {
  background-color: transparent;
  color: var(--hh-forest-green);
  box-shadow: none;
}

.hh-hero-search-btn {
  background-color: var(--hh-forest-green);
  color: var(--hh-cream);
  border: 1px solid var(--hh-forest-green);
  border-radius: 7px;
  font-size: 0.95rem;
  font-weight: 700;
  padding: 0.55rem 1.25rem;
  flex-shrink: 0;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.hh-hero-search-btn:hover,
.hh-hero-search-btn:focus-visible {
  background-color: #14492d;
  border-color: #14492d;
  color: var(--hh-cream);
}

/* ==========================================================================
   REGION FILTERS & POPULAR DESTINATIONS SECTION
   ========================================================================== */

.hh-destinations-section {
  padding: 2.5rem 0 4rem;
}

.hh-destinations-container {
  max-width: 1120px;
}

/* Region filter buttons */
.hh-filter-bar {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.75rem;
  margin-bottom: 2.25rem;
}

.hh-filter-btn {
  background-color: #ffffff;
  color: var(--hh-forest-green);
  border: 1.5px solid var(--hh-forest-green);
  border-radius: 999px;
  font-size: 0.92rem;
  font-weight: 400;
  padding: 0.5rem 1.35rem;
  transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.hh-filter-btn:hover {
  background-color: rgba(217, 179, 130, 0.28);
  color: var(--hh-forest-green);
}

.hh-filter-btn:focus-visible {
  outline: 2px solid var(--hh-earthy-orange);
  outline-offset: 2px;
}

.hh-filter-btn.active {
  background-color: var(--hh-forest-green);
  border-color: var(--hh-forest-green);
  color: var(--hh-cream);
  font-weight: 700;
  box-shadow: inset 0 -3px 0 var(--hh-earthy-orange);
}

/* Section heading */
.hh-section-header {
  margin-bottom: 1.5rem;
  padding-bottom: 0.75rem;
  border-bottom: 1.5px solid var(--hh-sand-beige);
}

.hh-section-title {
  color: var(--hh-forest-green);
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  font-weight: 700;
  margin-bottom: 0;
}

/* ==========================================================================
   DESTINATION CARDS (2-column grid on desktop)
   ========================================================================== */

.hh-destination-card {
  background-color: #ffffff;
  border: 1px solid var(--hh-sand-beige);
  border-radius: 12px;
  overflow: hidden;
  height: 100%;
  display: flex;
  flex-direction: column;
  box-shadow: 0 4px 14px rgba(27, 94, 59, 0.06);
}

.hh-card-media {
  position: relative;
  width: 100%;
  height: 240px;
  background-color: #ece6d3;
  overflow: hidden;
}

.hh-card-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

/* Graceful placeholder shown when real destination photo is not added yet */
.hh-card-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 1.25rem;
  text-align: center;
  background: linear-gradient(155deg, rgba(167, 201, 87, 0.3) 0%, rgba(217, 179, 130, 0.35) 100%);
  color: var(--hh-forest-green);
}

.hh-placeholder-icon {
  width: 56px;
  height: 40px;
  opacity: 0.85;
}

.hh-placeholder-title {
  font-size: 0.95rem;
  font-weight: 700;
}

.hh-placeholder-note {
  font-size: 0.78rem;
  color: var(--hh-olive-green);
}

.hh-card-body {
  padding: 1.35rem 1.4rem 1.5rem;
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
}

.hh-region-badge {
  display: inline-block;
  align-self: flex-start;
  background-color: rgba(201, 123, 61, 0.14);
  color: #8f4a16;
  border: 1px solid rgba(201, 123, 61, 0.4);
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
  padding: 0.22rem 0.7rem;
  margin-bottom: 0.75rem;
}

.hh-card-title {
  color: var(--hh-forest-green);
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: 0.45rem;
}

.hh-card-desc {
  color: var(--hh-olive-green);
  font-size: 0.95rem;
  line-height: 1.55;
  margin-bottom: 1.25rem;
}

.hh-card-actions {
  margin-top: auto;
}

.hh-explore-btn {
  background-color: var(--hh-forest-green);
  color: var(--hh-cream);
  border: 1px solid var(--hh-forest-green);
  border-radius: 8px;
  font-size: 0.92rem;
  font-weight: 700;
  padding: 0.55rem 1.2rem;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.hh-explore-btn:hover,
.hh-explore-btn:focus-visible {
  background-color: var(--hh-earthy-orange);
  border-color: var(--hh-earthy-orange);
  color: var(--hh-cream);
}

/* ==========================================================================
   EMPTY STATE MESSAGE
   ========================================================================== */

.hh-empty-state {
  background-color: rgba(255, 255, 255, 0.75);
  border: 1.5px dashed var(--hh-sand-beige);
  border-radius: 12px;
  padding: 2.5rem 1.5rem;
  text-align: center;
  margin-top: 1rem;
}

.hh-empty-state-text {
  color: var(--hh-forest-green);
  font-size: 1.05rem;
}

.hh-reset-btn {
  background-color: var(--hh-forest-green);
  color: var(--hh-cream);
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 700;
  padding: 0.5rem 1.2rem;
}

.hh-reset-btn:hover,
.hh-reset-btn:focus-visible {
  background-color: #14492d;
  color: var(--hh-cream);
}

/* ==========================================================================
   RESPONSIVE ADJUSTMENTS
   ========================================================================== */

@media (max-width: 575.98px) {
  .hh-hero {
    padding: 2.5rem 0.75rem 2.75rem;
  }

  .hh-hero-search {
    flex-direction: column;
    padding: 0.5rem;
  }

  .hh-hero-search-btn {
    width: 100%;
  }

  .hh-card-media {
    height: 205px;
  }
}

/**
 * Highland Horizons — Destinations Page Script
 * Renders destination cards from a JavaScript data array and handles
 * combined region filtering and destination name search.
 */
(function () {
  "use strict";

  // Data array for the Popular Destinations cards.
  // To add real photos later, place the image files in assets/images/destinations/
  // and update each item's "image" property (for example: "../assets/images/destinations/hunza-valley.jpg").
  var DESTINATIONS = [
    {
      id: "hunza-valley",
      name: "Hunza Valley",
      description: "Explore Hunza's beauty",
      region: "Gilgit-Baltistan",
      image: "",
      suggestedFile: "assets/images/destinations/hunza-valley.jpg",
      imageAlt: "Scenic view of Hunza Valley in Gilgit-Baltistan"
    },
    {
      id: "skardu",
      name: "Skardu",
      description: "Discover Skardu",
      region: "Gilgit-Baltistan",
      image: "",
      suggestedFile: "assets/images/destinations/skardu.jpg",
      imageAlt: "Mountain lakes and peaks of Skardu in Gilgit-Baltistan"
    },
    {
      id: "swat-valley",
      name: "Swat Valley",
      description: "Green landscapes & rivers",
      region: "KPK",
      image: "",
      suggestedFile: "assets/images/destinations/swat-valley.jpg",
      imageAlt: "Lush green hills and rivers of Swat Valley in KPK"
    },
    {
      id: "naran-valley",
      name: "Naran Valley",
      description: "A scenic mountain escape",
      region: "KPK",
      image: "",
      suggestedFile: "assets/images/destinations/naran-valley.jpg",
      imageAlt: "Alpine mountains and valleys of Naran Valley in KPK"
    }
  ];

  // Current filter and search state
  var activeRegion = "All";
  var searchQuery = "";

  // DOM element references
  var gridEl = document.getElementById("destinationsGrid");
  var emptyStateEl = document.getElementById("emptyDestinationsMessage");
  var emptyMessageTextEl = document.getElementById("emptyMessageText");
  var searchFormEl = document.getElementById("destinationSearchForm");
  var searchInputEl = document.getElementById("destinationSearchInput");
  var resetBtnEl = document.getElementById("resetFiltersBtn");
  var filterButtons = document.querySelectorAll(".hh-filter-btn");

  /**
   * Builds a graceful placeholder block when an image file is not added yet.
   */
  function createImagePlaceholder(destination) {
    var wrapper = document.createElement("div");
    wrapper.className = "hh-card-placeholder";
    wrapper.setAttribute("role", "img");
    wrapper.setAttribute("aria-label", destination.imageAlt + " (image placeholder)");

    wrapper.innerHTML =
      '<svg class="hh-placeholder-icon" viewBox="0 0 64 46" fill="none" aria-hidden="true">' +
      '<path d="M4 40L21 15L33 31L42 20L60 40H4Z" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/>' +
      '<circle cx="48" cy="11" r="4.5" stroke="currentColor" stroke-width="2.2"/>' +
      "</svg>";

    var titleSpan = document.createElement("span");
    titleSpan.className = "hh-placeholder-title";
    titleSpan.textContent = destination.name + " Photo";

    var noteSpan = document.createElement("span");
    noteSpan.className = "hh-placeholder-note";
    noteSpan.textContent = "Add image: " + destination.suggestedFile;

    wrapper.appendChild(titleSpan);
    wrapper.appendChild(noteSpan);
    return wrapper;
  }

  /**
   * Creates the media container (real <img> when provided, or placeholder fallback).
   */
  function createCardMedia(destination) {
    var mediaBox = document.createElement("div");
    mediaBox.className = "hh-card-media";

    if (destination.image) {
      var img = document.createElement("img");
      img.className = "hh-card-img";
      img.src = destination.image;
      img.alt = destination.imageAlt;

      // Fall back gracefully if the image path fails to load
      img.addEventListener("error", function () {
        mediaBox.innerHTML = "";
        mediaBox.appendChild(createImagePlaceholder(destination));
      });

      mediaBox.appendChild(img);
    } else {
      mediaBox.appendChild(createImagePlaceholder(destination));
    }

    return mediaBox;
  }

  /**
   * Builds one responsive Bootstrap column containing a destination card.
   */
  function createDestinationCard(destination) {
    var col = document.createElement("div");
    col.className = "col";

    var article = document.createElement("article");
    article.className = "hh-destination-card";

    var media = createCardMedia(destination);

    var body = document.createElement("div");
    body.className = "hh-card-body";

    var regionBadge = document.createElement("span");
    regionBadge.className = "hh-region-badge";
    regionBadge.textContent = destination.region;

    var title = document.createElement("h3");
    title.className = "hh-card-title";
    title.textContent = destination.name;

    var description = document.createElement("p");
    description.className = "hh-card-desc";
    description.textContent = destination.description;

    var actions = document.createElement("div");
    actions.className = "hh-card-actions";

    var exploreLink = document.createElement("a");
    exploreLink.className = "btn hh-explore-btn";
    exploreLink.href = "destination-details.html?destination=" + encodeURIComponent(destination.id);
    exploreLink.textContent = "Explore";
    exploreLink.setAttribute("aria-label", "Explore " + destination.name);

    actions.appendChild(exploreLink);
    body.appendChild(regionBadge);
    body.appendChild(title);
    body.appendChild(description);
    body.appendChild(actions);

    article.appendChild(media);
    article.appendChild(body);
    col.appendChild(article);

    return col;
  }

  /**
   * Returns destinations matching BOTH the selected region and the search text.
   */
  function getFilteredDestinations() {
    var normalizedQuery = searchQuery.trim().toLowerCase();

    return DESTINATIONS.filter(function (destination) {
      var matchesRegion = activeRegion === "All" || destination.region === activeRegion;
      var matchesSearch =
        normalizedQuery === "" ||
        destination.name.toLowerCase().indexOf(normalizedQuery) !== -1;

      return matchesRegion && matchesSearch;
    });
  }

  /**
   * Updates the destination cards grid and empty-state message.
   */
  function renderDestinations() {
    if (!gridEl || !emptyStateEl) {
      return;
    }

    var filtered = getFilteredDestinations();
    gridEl.innerHTML = "";

    if (filtered.length === 0) {
      emptyStateEl.hidden = false;
      if (emptyMessageTextEl) {
        var trimmed = searchQuery.trim();
        if (trimmed && activeRegion !== "All") {
          emptyMessageTextEl.textContent =
            'No destinations found matching "' + trimmed + '" in ' + activeRegion + ".";
        } else if (trimmed) {
          emptyMessageTextEl.textContent =
            'No destinations found matching "' + trimmed + '".';
        } else {
          emptyMessageTextEl.textContent =
            "No destinations found in " + activeRegion + ".";
        }
      }
      return;
    }

    emptyStateEl.hidden = true;
    filtered.forEach(function (destination) {
      gridEl.appendChild(createDestinationCard(destination));
    });
  }

  /**
   * Highlights the active region button and updates aria-pressed for accessibility.
   */
  function setActiveRegionButton(selectedRegion) {
    filterButtons.forEach(function (button) {
      var isSelected = button.getAttribute("data-region") === selectedRegion;
      button.classList.toggle("active", isSelected);
      button.setAttribute("aria-pressed", String(isSelected));
    });
  }

  function initEvents() {
    filterButtons.forEach(function (button) {
      button.addEventListener("click", function () {
        activeRegion = button.getAttribute("data-region") || "All";
        setActiveRegionButton(activeRegion);
        renderDestinations();
      });
    });

    if (searchInputEl) {
      searchInputEl.addEventListener("input", function () {
        searchQuery = searchInputEl.value;
        renderDestinations();
      });
    }

    if (searchFormEl) {
      searchFormEl.addEventListener("submit", function (event) {
        event.preventDefault();
        if (searchInputEl) {
          searchQuery = searchInputEl.value;
        }
        renderDestinations();
      });
    }

    if (resetBtnEl) {
      resetBtnEl.addEventListener("click", function () {
        activeRegion = "All";
        searchQuery = "";
        if (searchInputEl) {
          searchInputEl.value = "";
        }
        setActiveRegionButton("All");
        renderDestinations();
      });
    }
  }

  document.addEventListener("DOMContentLoaded", function () {
    initEvents();
    renderDestinations();
  });
})();

