        searchInput.dispatchEvent(new Event("input", { bubbles: true }));
        assert("Combined KPK + 'hunza' shows 0 cards", doc.querySelectorAll(".hh-destination-card").length === 0);
        assert("Empty state message visible", emptyBox.hidden === false);

        // 7. Switch to All while search="hunza" -> 1 card (Hunza Valley)
        allBtn.click();
        var hunzaOnly = Array.from(doc.querySelectorAll(".hh-card-title")).map(function (el) { return el.textContent; });
        assert("All + 'hunza' shows 1 card (Hunza Valley)", hunzaOnly.length === 1 && hunzaOnly[0] === "Hunza Valley");
