    "file:///C:/Users/X1/Semester%201%20Projects/IICT%20project/E_Group_7_HighlandHorizons/pages/destinations.html"
) -Wait -RedirectStandardOutput $fileDomOut | Out-Null

Start-Process -FilePath $chrome -ArgumentList @(
    "--headless=new", "--disable-gpu", "--no-sandbox",
    "--user-data-dir=`"$userData`"",
    "--window-size=1440,1650",
    "--virtual-time-budget=3000",
    "--screenshot=`"$fileShot`"",
    "file:///C:/Users/X1/Semester%201%20Projects/IICT%20project/E_Group_7_HighlandHorizons/pages/destinations.html"
) -Wait | Out-Null

$fileDom = if (Test-Path $fileDomOut) { Get-Content $fileDomOut -Raw } else { "" }
Write-Output "--- FILE:// PROTOCOL CHECK ---"
Write-Output ("Header present in file://: " + ($fileDom -match 'class="hh-header"'))
Write-Output ("Footer present in file://: " + ($fileDom -match 'class="hh-footer"'))
Write-Output ("Logo src uses ../ in file://: " + ($fileDom -match 'src="\.\./assets/images/logo\.svg"'))
Write-Output ("4 cards rendered in file://: " + (([regex]::Matches($fileDom, 'class="hh-destination-card"')).Count -eq 4))
Write-Output ("File screenshot saved: " + (Test-Path $fileShot))

# 2. Test http:// rendering + full interactive check
$port = 8768
$prefix = "http://127.0.0.1:$port/"

$testRunnerHtml = @'
<!DOCTYPE html>
<html lang="en">
<head><meta charset="UTF-8"><title>Header Footer HTTP Verification</title></head>
<body>
<iframe id="appFrame" src="/pages/destinations.html" width="1280" height="900"></iframe>
<pre id="results">RUNNING</pre>
<script>
(function () {
  var resultsEl = document.getElementById("results");
  var frame = document.getElementById("appFrame");
  frame.addEventListener("load", function () {
    var doc = frame.contentDocument;
    setTimeout(function () {
      var out = [];
      function assert(name, cond) { out.push((cond ? "PASS" : "FAIL") + ": " + name); }
      var header = doc.querySelector(".hh-header");
      var footer = doc.querySelector(".hh-footer");
      var headerLogo = doc.querySelector(".hh-header-logo");
      var footerLogo = doc.querySelector(".hh-footer-logo");
      var activeLink = doc.querySelector('[data-hh-page="destinations"]');
      var imgs = Array.from(doc.querySelectorAll("#destinationsGrid img.hh-card-img"));
      assert("Header present over HTTP", !!header);
      assert("Footer present over HTTP", !!footer);
      assert("Header logo loaded", !!(headerLogo && headerLogo.complete && headerLogo.naturalWidth > 0));
      assert("Footer logo loaded", !!(footerLogo && footerLogo.complete && footerLogo.naturalWidth > 0));
      assert("Destinations nav link active", !!(activeLink && activeLink.classList.contains("active")));
      assert("All 4 card photos loaded", imgs.length === 4 && imgs.every(function (i) { return i.complete && i.naturalWidth > 0; }));
      doc.querySelector('.hh-filter-btn[data-region="Gilgit-Baltistan"]').click();
      assert("Region filter works (2 cards)", doc.querySelectorAll(".hh-destination-card").length === 2);
      var searchInput = doc.getElementById("destinationSearchInput");
      searchInput.value = "skardu";
      searchInput.dispatchEvent(new Event("input", { bubbles: true }));
      assert("Combined filter + search works (1 card)", doc.querySelectorAll(".hh-destination-card").length === 1);
      resultsEl.textContent = out.join("\n");
    }, 1000);
  });
})();
</script>
</body>
</html>
'@

$listener = New-Object System.Net.HttpListener
$listener.Prefixes.Add($prefix)
$listener.Start()

$runspace = [runspacefactory]::CreateRunspace()
$runspace.Open()
$ps = [powershell]::Create()
$ps.Runspace = $runspace
[void]$ps.AddScript({
    param($listenerObj, $rootDir, $runnerHtml)
    $mimeTypes = @{ ".html"="text/html; charset=utf-8"; ".css"="text/css; charset=utf-8"; ".js"="application/javascript; charset=utf-8"; ".svg"="image/svg+xml"; ".jpg"="image/jpeg" }
    while ($listenerObj.IsListening) {
        try {
            $ctx = $listenerObj.GetContext()
            $relPath = $ctx.Request.Url.AbsolutePath.TrimStart("/")
            if ($relPath -eq "__test_hf.html") {
                $ctx.Response.ContentType = "text/html; charset=utf-8"
                $bytes = [System.Text.Encoding]::UTF8.GetBytes($runnerHtml)
                $ctx.Response.StatusCode = 200
                $ctx.Response.OutputStream.Write($bytes, 0, $bytes.Length)
                $ctx.Response.Close()
                continue
            }
            $fullPath = Join-Path $rootDir ($relPath -replace "/", "\")
            if (Test-Path $fullPath -PathType Leaf) {
                $ext = [System.IO.Path]::GetExtension($fullPath).ToLower()
                $ctx.Response.ContentType = if ($mimeTypes.ContainsKey($ext)) { $mimeTypes[$ext] } else { "application/octet-stream" }
                $bytes = [System.IO.File]::ReadAllBytes($fullPath)
                $ctx.Response.StatusCode = 200
                $ctx.Response.OutputStream.Write($bytes, 0, $bytes.Length)
            } else {
                $ctx.Response.StatusCode = 404
            }
            $ctx.Response.Close()
        } catch { break }
    }
}).AddArgument($listener).AddArgument($root).AddArgument($testRunnerHtml)
$async = $ps.BeginInvoke()

try {
    $httpDomOut = Join-Path $scratch "http-dom-out.html"
    Start-Process -FilePath $chrome -ArgumentList @(
        "--headless=new", "--disable-gpu", "--no-sandbox",
        "--user-data-dir=`"$userData`"",
        "--virtual-time-budget=5000",
        "--dump-dom",
        ($prefix + "__test_hf.html")
    ) -Wait -RedirectStandardOutput $httpDomOut | Out-Null

    $httpDom = if (Test-Path $httpDomOut) { Get-Content $httpDomOut -Raw } else { "" }
    if ($httpDom -match '(?s)<pre id="results">(.*?)</pre>') {
        Write-Output "--- HTTP PROTOCOL CHECK ---"
        Write-Output $Matches[1].Trim()
    } else {
        Write-Output "Could not extract HTTP test results."
    }
} finally {
    $listener.Stop()
    $listener.Close()
    $ps.Dispose()
    $runspace.Close()
}
